True def transform(grid):
    """Extend colors across repeating anti-diagonal bands of width three."""
    h, w = len(grid), len(grid[0])
    bands = {}
    counts = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                k = (r + c) % 3
                counts.setdefault(k, {})[color] = counts.setdefault(k, {}).get(color, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    band_color = {k: max(cs, key=cs.get) for k, cs in counts.items()}
    all_counts = {}
    for cs in counts.values():
        for color, n in cs.items():
            all_counts[color] = all_counts.get(color, 0) + n
    fallback = max(all_counts, key=all_counts.get)
    return [[band_color.get((r+c)%3, fallback) for c in range(w)] for r in range(h)]
